('9d411cb7-3013-5742-b57e-c7a42defeda1', '0cb78bec-f840-5f54-bdeb-58593a417c0b', 'Welcome back to the 2025-2026 school year', 'Classes resume Monday. Please collect timetables from the front office and review the updated code of conduct posted on the notice board.', 'all', NULL, '2025-09-25 08:00:00', NULL),
('aca94cf7-84fa-56f0-b7f8-b4e7af8c76e0', '0cb78bec-f840-5f54-bdeb-58593a417c0b', 'Staff meeting — Thursday 3:30 PM', 'All teaching staff should attend the term-planning meeting in the staff room. Department heads, please bring your assessment calendars.', 'teachers', NULL, '2025-10-09 14:00:00', '2025-10-17 00:00:00'),
('24f59868-e21c-542f-be49-e368e406242b', '9b3e3ff5-1282-55b7-888f-cd4ff7e9d4b5', 'Midterm exam schedule released', 'The midterm timetable is now available. Review your subjects and prepare accordingly. Speak to your teachers about any clashes.', 'students', NULL, '2025-10-11 10:00:00', NULL),
('f6d2813f-3583-5b4c-89bd-354e94e38357', '57eb7c25-18b2-5789-a329-39a99e277c9a', 'Form 1A — bring lab coats Friday', 'For our first Biology practical this Friday, all Form 1A students must bring a lab coat and closed-toe shoes.', 'class', '02cc8348-d9e4-5eb9-88e9-b0ff39a40184', '2025-10-13 11:30:00', '2025-10-18 00:00:00'),
('3ccbc5fd-da62-5bd8-ac00-44c41877bc79', '9167ab7e-9fa6-5f2d-914b-318f6733b3d6', 'Sports Day — save the date', 'Annual Sports Day is scheduled for next month. House captains will be announced shortly. Get your teams ready!', 'all', NULL, '2025-10-14 09:00:00', NULL),
('f58f6f76-fcd9-53ba-b43e-23d0ea2a1fc2', '9b3e3ff5-1282-55b7-888f-cd4ff7e9d4b5', 'Library closed for stocktake (expired)', 'The library was closed last week for the annual stocktake. It has since reopened for normal hours.', 'all', NULL, '2025-10-03 08:00:00', '2025-10-07 00:00:00');
